from policy.capabilities import Capability as C,Decision as D
PROFILES={
'READ_ONLY':{C.FS_READ:D.ALLOW,C.FS_READ_SECRETS:D.DENY,C.FS_WRITE:D.DENY,C.SHELL_EXEC:D.DENY,C.GIT_READ:D.ALLOW,C.GIT_WRITE:D.DENY,C.NETWORK_LOCAL:D.DENY,C.NETWORK_EXTERNAL:D.DENY,C.PROCESS_SIGNAL:D.DENY},
'SAFE':{C.FS_READ:D.ALLOW,C.FS_READ_SECRETS:D.APPROVE,C.FS_WRITE:D.APPROVE,C.SHELL_EXEC:D.APPROVE,C.SHELL_INSTALL:D.APPROVE,C.GIT_READ:D.ALLOW,C.GIT_WRITE:D.APPROVE,C.NETWORK_LOCAL:D.APPROVE,C.NETWORK_EXTERNAL:D.DENY,C.PROCESS_SIGNAL:D.APPROVE},
'NORMAL':{C.FS_READ:D.ALLOW,C.FS_READ_SECRETS:D.APPROVE,C.FS_WRITE:D.ALLOW,C.SHELL_EXEC:D.ALLOW,C.SHELL_INSTALL:D.APPROVE,C.GIT_READ:D.ALLOW,C.GIT_WRITE:D.APPROVE,C.NETWORK_LOCAL:D.ALLOW,C.NETWORK_EXTERNAL:D.APPROVE,C.PROCESS_SIGNAL:D.ALLOW},
}
def decision(profile:str,cap:C)->D:return PROFILES.get(profile,{}).get(cap,D.DENY)
